#include "capability_declarations.hpp"
#include <algorithm>
#include <set>
#include <stdexcept>
namespace axon::portfolio { namespace { std::set<std::string> set_of(const std::vector<std::string>& v){return {v.begin(),v.end()};} double overlap(const std::vector<std::string>& a,const std::vector<std::string>& b){auto x=set_of(a),y=set_of(b);if(x.empty()||y.empty())return 0;size_t n=0;for(const auto&i:x)n+=y.contains(i);return static_cast<double>(n)/static_cast<double>(x.size()+y.size()-n);} }
DeclarationComparison compare_declarations(const std::vector<CapabilitySignature>& observed,const std::vector<DeclaredCapability>& declared){ DeclarationComparison out; for(const auto&o:observed){std::vector<const DeclaredCapability*> candidates;for(const auto&d:declared)if(o.normalized_name==d.normalized_name&&(!o.bounded_context||d.bounded_context.empty()||*o.bounded_context==d.bounded_context))candidates.push_back(&d);const auto oid=o.stream.repository_id+":"+o.stream.index_stream_id+":"+o.signature_id;if(candidates.empty()){out.drift.push_back({CapabilityDriftKind::observed_without_declaration,oid,"no declared capability matches observed metadata"});continue;}if(candidates.size()!=1){out.drift.push_back({CapabilityDriftKind::ambiguous_match,oid,"multiple declarations match; ownership remains unresolved"});continue;}const auto score=.6+.4*overlap(o.contracts,candidates[0]->contracts);out.matches.push_back({oid,candidates[0]->id,score,{"normalized_name match"},false});}for(const auto&d:declared){const bool observed_metadata_match=std::any_of(observed.begin(),observed.end(),[&](const auto&o){return o.normalized_name==d.normalized_name&&(!o.bounded_context||d.bounded_context.empty()||*o.bounded_context==d.bounded_context);});if(!observed_metadata_match)out.drift.push_back({CapabilityDriftKind::declaration_without_observed,d.id,"no observed implementation matches declaration"});}return out;}
} // namespace axon::portfolio
